const cfg = $('Config (Rel)').first().json;
const hoje = $now.startOf('day');
const fim = hoje.minus({ days: 1 });                 // até ontem (dia fechado, igual ao Gerenciador)
let ini;
if (String(cfg.periodo_modo) === 'ultimos_dias') ini = hoje.minus({ days: Math.max(1, Number(cfg.periodo_dias) || 7) });
else { let d = hoje.minus({ days: 1 }); while (![2, 5].includes(d.weekday)) d = d.minus({ days: 1 }); ini = d; } // último dia de relatório (ter/sex)
const dias = Math.round(fim.diff(ini, 'days').days) + 1;
const fimAnt = ini.minus({ days: 1 }), iniAnt = fimAnt.minus({ days: dias - 1 });
const f = d => d.toFormat('yyyy-MM-dd'), b = d => d.toFormat('dd/MM');
return [{ json: { since: f(ini), until: f(fim), since_ant: f(iniAnt), until_ant: f(fimAnt), dias,
  rotulo: dias === 1 ? b(ini) : `${b(ini)} a ${b(fim)}`, hoje: f(hoje) } }];

// ===== utilitários padrão Konext (iguais em todos os fluxos) =====
const n_ = s => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]/g, '');
const pick = (row, nomes) => {
  const m = {};
  for (const k of Object.keys(row || {})) m[n_(k)] = row[k];
  for (const nome of nomes) { const v = m[n_(nome)]; if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); }
  return '';
};
const dig = v => String(v ?? '').replace(/\D/g, '');
const sim = (v, padrao) => { const t = n_(v); if (!t) return padrao; return ['sim', 's', 'yes', 'y', 'true', '1', 'ativo'].includes(t); };
const nao = v => ['nao', 'n', 'no', 'false', '0', 'inativo'].includes(n_(v));
const money = v => {
  let s = String(v ?? '').replace(/[^\d,.\-]/g, '');
  if (!s) return null;
  const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > -1 && p > -1) s = c > p ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  else if (c > -1) s = s.replace(',', '.');
  else if (/^\d{1,3}(\.\d{3})+$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s); return isNaN(n) ? null : n;
};
// Número de WhatsApp ou ID de grupo -> formato aceito pela Evolution API
const jid = v => {
  const s = String(v ?? '').trim();
  if (!s) return '';
  if (/@g\.us$/i.test(s)) return s.replace(/\s/g, '');
  const d = s.replace(/\D/g, '');
  if (!d) return '';
  if (d.startsWith('120363') && d.length >= 15) return d + '@g.us';
  return d.length <= 11 ? '55' + d : d;
};

const cfg = $('Config (Rel)').first().json;
const preferirGrupo = !(cfg.preferir_grupo === false || cfg.preferir_grupo === 'false');
const grupos = $('Grupos WhatsApp (Rel)').all().map(i => i.json || {}).filter(g => !g.error)
  .map(g => ({ nome: pick(g, ['Grupo', 'Nome do Grupo', 'Nome']), id: pick(g, ['ID', 'ID do Grupo']).replace(/\s/g, ''), ativo: !nao(pick(g, ['Ativo'])) }))
  .filter(g => g.ativo && /@g\.us$/i.test(g.id))
  .map(g => ({ ...g, chave: n_(g.nome) }));
// Procura o grupo do cliente pelo nome / apelidos (só aceita quando há UM grupo compatível)
const acharGrupo = (cliente, apelidos) => {
  const cands = [cliente, ...apelidos].map(n_).filter(c => c.length >= 4);
  let m = grupos.filter(g => cands.some(c => g.chave.includes(c)));
  if (m.length === 1) return m[0];
  if (m.length > 1) return null;
  const primeiro = n_(String(cliente).trim().split(/\s+/)[0]);
  if (primeiro.length >= 4) { m = grupos.filter(g => g.chave.includes(primeiro)); if (m.length === 1) return m[0]; }
  return null;
};
// Destino: grupo do cliente (coluna "ID do Grupo" ou planilha de grupos) e, se não houver, o "Contato do cliente".
// O "Contato do cliente" também pode conter direto um ID de grupo (120363...@g.us).
const montarDestino = (cliente, apelidos, contatoRaw, grupoRaw) => {
  const contato = jid(contatoRaw);
  const fixo = jid(grupoRaw);
  const g = fixo.endsWith('@g.us') ? { id: fixo, nome: '(ID do Grupo na planilha)' } : acharGrupo(cliente, apelidos);
  let destino = '', destino_desc = '';
  const porGrupo = () => { destino = g.id; destino_desc = 'grupo ' + g.nome; };
  const porContato = () => { destino = contato; destino_desc = (contato.endsWith('@g.us') ? 'grupo ' : 'WhatsApp ') + contato; };
  if (preferirGrupo) { if (g) porGrupo(); else if (contato) porContato(); }
  else { if (contato) porContato(); else if (g) porGrupo(); }
  return { contato, grupo: g ? g.id : '', grupo_nome: g ? g.nome : '', destino, destino_desc };
};
const clientes = []; const vistos = new Set();
for (const it of $('Clientes Geral (Rel)').all()) {
  const r = it.json || {};
  if (r.error) continue;
  if (!sim(pick(r, ['Status', 'Ativo']), false)) continue;           // Status = Ativo
  const conta = dig(pick(r, ['ID da Conta', 'Conta de Anuncio', 'Conta de Anúncio', 'Conta']));
  const cliente = pick(r, ['Cliente', 'Clientes', 'Nome do cliente', 'Nome']);
  if (!conta || vistos.has(conta)) continue;
  vistos.add(conta);
  const apelidos = pick(r, ['Apelido', 'Apelidos']).split(',').map(s => s.trim()).filter(Boolean);
  clientes.push({
    row_number: r.row_number, cliente: cliente || ('Conta ' + conta), conta, apelidos,
    ...montarDestino(cliente, apelidos, pick(r, ['Contato do cliente', 'Contato', 'WhatsApp do cliente', 'Telefone']), pick(r, ['ID do Grupo', 'Grupo WhatsApp', 'Grupo do cliente'])),
    valor_base: money(pick(r, ['Valor Base'])),
    reativar: sim(pick(r, ['Reativar na Segunda', 'Reativar toda segunda', 'Reativar toda segunda-feira', 'Reativar']), true),
    monitorar: sim(pick(r, ['Monitorar Custo']), true),
    pagina: dig(pick(r, ['ID da Página', 'ID da Pagina'])),
    ig_id: dig(pick(r, ['ID Instagram', 'ID do Instagram'])),
    ig_user: pick(r, ['Instagram (usuário)', 'Usuário do Instagram', 'Instagram']).replace(/^@/, ''),
    whatsapp_campanha: jid(pick(r, ['WhatsApp da Campanha', 'WhatsApp'])),
    link_relatorio: pick(r, ['Link do Relatório', 'Link do Relatorio', 'Link Relatório', 'Relatório', 'Link do Dashboard']),
    enviar_relatorio: sim(pick(r, ['Enviar Relatório', 'Enviar Relatorio']), true),
    rel_melhorias: pick(r, ['Relatório - Melhorias', 'Melhorias']),
    rel_ajustes: pick(r, ['Relatório - Ajustes', 'Ajustes']),
  });
}

const metodo = {};
for (const p of $('Planilha de Saldo (Rel)').all().map(i => i.json || {})) {
  if (p.error) continue;
  const c = dig(pick(p, ['Conta de Anuncio', 'Conta de Anúncio', 'ID da Conta']));
  if (c && !metodo[c]) metodo[c] = pick(p, ['Metodo de Pagamento', 'Método de Pagamento']);
}
const sd = $getWorkflowStaticData('global');
sd.exec_rel = { [String($execution.id)]: {} };
return clientes.filter(c => c.enviar_relatorio).map(c => ({ json: { ...c, metodo: metodo[c.conta] || '' } }));

const cfg = $('Config (Rel)').first().json;
const per = $('Período (Rel)').first().json;
const cli = $('Loop Clientes (Rel)').first().json;
const J = name => { try { return $(name).first().json || {}; } catch (e) { return { error: 'etapa não executada' }; } };
const errTxt = e => { if (e && typeof e === 'object') e = e.message || e.error_user_msg || JSON.stringify(e); return String(e ?? '').slice(0, 250); };
const num = v => { const n = parseFloat(v); return isNaN(n) ? 0 : n; };
const milhar = s => s.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const brl = n => { const [i, d] = Number(n).toFixed(2).split('.'); return 'R$ ' + milhar(i) + ',' + d; };
const int = n => milhar(Math.round(n).toString());
const pct = n => n.toFixed(1).replace('.', ',').replace(',0', '');
const listaOk = r => r && !r.error && Array.isArray(r.data);
const gestor = String(cfg.numero_gestor);
const teste = cfg.modo_teste === true || cfg.modo_teste === 'true';

const sd = $getWorkflowStaticData('global'); const ek = String($execution.id);
sd.exec_rel = sd.exec_rel || {}; sd.exec_rel[ek] = sd.exec_rel[ek] || {};
const rec = sd.exec_rel[ek][cli.conta] = { cliente: cli.cliente, status: '-', aviso: '-', obs: '' };
const saida = (envios, qtdCliente) => [{ json: { cliente: cli.cliente, conta: cli.conta, destino: cli.destino, qtd_ok: qtdCliente, envios, tem_envios: envios.length > 0 } }];

const conta = J('Conta (Rel)'), insConta = J('Insights Conta (Rel)'), insGen = J('Insights Público (Rel)');
const camps = J('Campanhas (Rel)'), insCamp = J('Insights Campanhas (Rel)'), insSet = J('Insights Conjuntos (Rel)');
const insSetAnt = J('Insights Conjuntos Anterior (Rel)'), adsP = J('Anúncios Pausados (Rel)'), ativ = $input.first().json || {};

// ---------- 1) Sem os dados essenciais NÃO envia nada ao cliente (nunca manda número errado)
const falhas = [['totais da conta', insConta], ['lista de campanhas', camps], ['campanhas', insCamp], ['conjuntos', insSet]]
  .filter(([, r]) => !listaOk(r)).map(([n, r]) => `• ${n}: ${errTxt(r.error ?? 'sem resposta')}`);
const incompleto = [['campanhas', insCamp], ['conjuntos', insSet], ['lista de campanhas', camps]]
  .filter(([, r]) => listaOk(r) && r.paging && r.paging.next).map(([n]) => n);
if (falhas.length || incompleto.length) {
  rec.status = 'NÃO ENVIADO'; rec.obs = falhas.length ? 'erro ao ler a Meta' : 'dados incompletos';
  return saida([{ para: gestor, tipo: 'gestor', texto: `⚠️ *Relatório NÃO enviado — ${cli.cliente}*\n\nConta: ${cli.conta}\nPeríodo: ${per.rotulo}\n\n${falhas.join('\n')}${incompleto.length ? `\n• Resposta da Meta veio paginada (mais de 500 linhas) em: ${incompleto.join(', ')}` : ''}\n\nPara não enviar números divergentes, o cliente não recebeu o relatório. Confira o token/permissões e rode de novo.` }], 0);
}

// ---------- 2) Ações (mesmos tipos de ação do Monitor de CPR)
const acoes = arr => { const m = {}; for (const a of arr || []) m[a.action_type] = (m[a.action_type] || 0) + num(a.value); return m; };
const rxVisita = new RegExp(cfg.acao_visitas_regex || 'profile_visit', 'i');
const resMsg = a => num(a[cfg.acao_mensagens]);
const resVis = a => { if (a[cfg.acao_visitas] !== undefined) return num(a[cfg.acao_visitas]); let m = 0; for (const [k, v] of Object.entries(a)) if (rxVisita.test(k)) m = Math.max(m, v); return m; };
const TIPOS = {
  mensagens: { rotulo: 'mensagens', custo: 'Custo por mensagem', res: resMsg, meta: num(cfg.cpr_msg_meta), max: num(cfg.cpr_msg_max) },
  visitas: { rotulo: 'visitas ao perfil', custo: 'Custo por visita', res: resVis, meta: num(cfg.cpr_visita_max), max: num(cfg.cpr_visita_max) },
  cliques: { rotulo: 'cliques no link', custo: 'Custo por clique', res: a => num(a['link_click']), meta: 0, max: 0 },
  lp: { rotulo: 'visualizações da página', custo: 'Custo por visualização', res: a => num(a['landing_page_view']), meta: 0, max: 0 },
  leads: { rotulo: 'cadastros', custo: 'Custo por cadastro', res: a => num(a['lead']) || num(a['onsite_conversion.lead_grouped']) || num(a['offsite_conversion.fb_pixel_lead']), meta: 0, max: 0 },
  engaj: { rotulo: 'engajamentos', custo: 'Custo por engajamento', res: a => num(a['post_engagement']), meta: 0, max: 0 },
};
const tipoGoal = g => ({ CONVERSATIONS: 'mensagens', REPLIES: 'mensagens', VISIT_INSTAGRAM_PROFILE: 'visitas', PROFILE_VISIT: 'visitas',
  INSTAGRAM_PROFILE_VISIT: 'visitas', LINK_CLICKS: 'cliques', LANDING_PAGE_VIEWS: 'lp', LEAD_GENERATION: 'leads', QUALITY_LEAD: 'leads',
  POST_ENGAGEMENT: 'engaj' })[String(g || '').toUpperCase()] || null;

// ---------- 3) Custo por resultado da campanha = MÉDIA do custo por resultado dos CONJUNTOS que tiveram resultado
const agrupar = rows => {
  const m = {};
  for (const s of rows || []) {
    const tipo = tipoGoal(s.optimization_goal), a = acoes(s.actions), spend = num(s.spend);
    const c = m[s.campaign_id] = m[s.campaign_id] || { conjuntos: [], gastoTipo: {} };
    const res = tipo ? TIPOS[tipo].res(a) : 0;
    c.conjuntos.push({ id: s.adset_id, tipo, spend, res, cpr: res > 0 ? spend / res : null });
    if (tipo) c.gastoTipo[tipo] = (c.gastoTipo[tipo] || 0) + spend;
  }
  const out = {};
  for (const [id, c] of Object.entries(m)) {
    const tipo = (Object.entries(c.gastoTipo).sort((x, y) => y[1] - x[1])[0] || [null])[0];
    if (!tipo) { out[id] = { tipo: null, resultados: 0, cpr: null, n: 0 }; continue; }
    const doTipo = c.conjuntos.filter(s => s.tipo === tipo), com = doTipo.filter(s => s.res > 0);
    out[id] = { tipo, resultados: doTipo.reduce((t, s) => t + s.res, 0), n: com.length,
                cpr: com.length ? com.reduce((t, s) => t + s.cpr, 0) / com.length : null };
  }
  return out;
};
const atual = agrupar(insSet.data);
const anterior = listaOk(insSetAnt) && !(insSetAnt.paging && insSetAnt.paging.next) ? agrupar(insSetAnt.data) : null;
const adsetCamp = Object.fromEntries(insSet.data.map(s => [s.adset_id, s.campaign_id]));

// ---------- 4) Totais da conta (mesmos números do Gerenciador / Konext Gestão para o período)
const tot = insConta.data[0] || {};
const aTot = acoes(tot.actions);
const T = { spend: num(tot.spend), reach: num(tot.reach), imp: num(tot.impressions), msgs: resMsg(aTot), vis: resVis(aTot) };
const somaCamp = insCamp.data.reduce((t, c) => t + num(c.spend), 0);
const divergencia = Math.abs(somaCamp - T.spend) > Math.max(1, T.spend * 0.01);
if (T.spend <= 0 && !(cfg.enviar_sem_investimento === true || cfg.enviar_sem_investimento === 'true')) {
  rec.status = 'Sem investimento'; rec.obs = 'nada investido no período — relatório não enviado';
  return saida([], 0);
}

// ---------- 5) Público
let publico = '';
if (listaOk(insGen)) {
  const met = cfg.publico_metrica === 'impressions' ? 'impressions' : 'reach';
  let f = 0, h = 0;
  for (const g of insGen.data) { if (g.gender === 'female') f += num(g[met]); if (g.gender === 'male') h += num(g[met]); }
  if (f + h > 0) publico = `${pct(f / (f + h) * 100)}% mulheres, ${pct(h / (f + h) * 100)}% homens`;
}

// ---------- 6) Campanhas: ativas x pausadas
const statusCamp = Object.fromEntries(camps.data.map(c => [String(c.id), c]));
const insPorCamp = Object.fromEntries(insCamp.data.map(c => [String(c.campaign_id), c]));
const ATIVO = ['ACTIVE', 'IN_PROCESS', 'WITH_ISSUES'];
const escaladas = new Set();
if (listaOk(ativ)) {
  const val = v => (v && typeof v === 'object') ? num(v.old_value ?? v.new_value ?? v.value ?? v.daily_budget ?? v.lifetime_budget) : num(v);
  for (const e of ativ.data) {
    if (!/budget/i.test(String(e.event_type))) continue;
    let x = e.extra_data; try { if (typeof x === 'string') x = JSON.parse(x); } catch (er) { continue; }
    if (!x || val(x.new_value) <= val(x.old_value) || val(x.old_value) <= 0) continue;
    const id = String(e.object_id);
    escaladas.add(statusCamp[id] ? id : String(adsetCamp[id] || ''));
  }
}
const ativas = camps.data.filter(c => ATIVO.includes(String(c.effective_status))).map(c => {
  const i = insPorCamp[String(c.id)] || {}, r = atual[String(c.id)] || { tipo: null, resultados: 0, cpr: null };
  const ant = anterior ? anterior[String(c.id)] : null;
  return { id: String(c.id), nome: c.name, spend: num(i.spend), freq: num(i.frequency), ...r,
           cpr_ant: ant && ant.tipo === r.tipo ? ant.cpr : null, escalada: escaladas.has(String(c.id)) };
});
const lim = c => (c.tipo && TIPOS[c.tipo].max) || 0;
const melhores = ativas.filter(c => c.spend > 0 && c.cpr !== null && (!lim(c) || c.cpr <= lim(c)))
  .sort((x, y) => (lim(x) ? x.cpr / lim(x) : 1) - (lim(y) ? y.cpr / lim(y) : 1)).slice(0, Number(cfg.top_campanhas) || 3);
const idsMelhores = new Set(melhores.map(c => c.id));
const demais = ativas.filter(c => !idsMelhores.has(c.id)).sort((x, y) => y.spend - x.spend);
const linhaCamp = c => {
  if (!c.spend) return `• *${c.nome}* — sem entrega no período`;
  let t = `• *${c.nome}*\n   💰 ${brl(c.spend)}`;
  if (c.tipo) t += ` | ${int(c.resultados)} ${TIPOS[c.tipo].rotulo}${c.cpr !== null ? ` | ${TIPOS[c.tipo].custo}: ${brl(c.cpr)}` : ''}`;
  if (c.escalada) t += '\n   🚀 Escalada (orçamento aumentado)';
  return t;
};

// pausadas: registro do Monitor de CPR (aba "Pausas CPR") + criativos pausados no período
const linkAd = a => a.preview_shareable_link || `https://adsmanager.facebook.com/adsmanager/manage/ads?act=${cli.conta}&selected_ad_ids=${a.id}`;
const adsLista = listaOk(adsP) ? adsP.data : [];
const iniMs = DateTime.fromISO(per.since, { zone: $now.zoneName }).toMillis();
const logItens = $('Pausas CPR (Rel)').all().map(i => i.json || {});
const logOk = !logItens.some(l => l.error);
const pausadas = new Map();
for (const l of logItens) {
  if (l.error || String(l['ID da Conta'] ?? '').replace(/\D/g, '') !== cli.conta) continue;
  const d = DateTime.fromFormat(String(l['Data'] ?? ''), 'dd/MM/yyyy HH:mm', { zone: $now.zoneName });
  if (!d.isValid || d.toMillis() < iniMs) continue;
  const id = String(l['ID Campanha'] ?? '').replace(/\D/g, '');
  if (!id || (statusCamp[id] && ATIVO.includes(String(statusCamp[id].effective_status)))) continue; // já reativada
  pausadas.set(id, { nome: l['Nome Campanha'] || id, motivo: l['Motivo'] || '', links: String(l['Anúncios'] || '').split(/\s+/).filter(Boolean) });
}
if (!logOk) {   // sem a aba de registro: campanhas pausadas no período que tiveram investimento
  for (const c of camps.data) {
    if (String(c.effective_status) !== 'PAUSED' || !insPorCamp[String(c.id)]) continue;
    if (DateTime.fromISO(String(c.updated_time || '')).toMillis() < iniMs) continue;
    pausadas.set(String(c.id), { nome: c.name, motivo: 'pausada no período', links: [] });
  }
}
for (const [id, p] of pausadas) {
  const daCamp = adsLista.filter(a => String(a.campaign_id) === id).map(linkAd);
  if (daCamp.length) p.links = daCamp;
}
// criativos pausados individualmente dentro de campanhas que seguem ativas
const criativos = adsLista.filter(a => String(a.effective_status) === 'PAUSED' && DateTime.fromISO(String(a.updated_time || '')).toMillis() >= iniMs
  && statusCamp[String(a.campaign_id)] && ATIVO.includes(String(statusCamp[String(a.campaign_id)].effective_status)));
const blocoPausa = [];
for (const [, p] of pausadas) {
  let t = `• *${p.nome}*${p.motivo ? ` — ${p.motivo}` : ''}`;
  const links = p.links.slice(0, 5);
  if (links.length) t += '\n' + links.map((l, i) => `   🎨 Criativo ${i + 1}: ${l}`).join('\n');
  if (p.links.length > 5) t += `\n   … e mais ${p.links.length - 5} criativo(s)`;
  blocoPausa.push(t);
}
const porCampCriativo = {};
for (const a of criativos) (porCampCriativo[String(a.campaign_id)] = porCampCriativo[String(a.campaign_id)] || []).push(a);
for (const [cid, lista] of Object.entries(porCampCriativo)) {
  blocoPausa.push(`• *${statusCamp[cid].name}* — criativo(s) pausado(s), campanha segue ativa\n` +
    lista.slice(0, 5).map(a => `   🎨 ${a.name}: ${linkAd(a)}`).join('\n'));
}

// ---------- 7) Melhorias e ajustes (automático + colunas opcionais da Planilha Geral)
const manual = t => String(t || '').split(/\n|;/).map(s => s.trim()).filter(Boolean).map(s => s.startsWith('•') ? s : '• ' + s);
const melhorias = manual(cli.rel_melhorias), ajustes = manual(cli.rel_ajustes);
for (const c of ativas) {
  if (!c.tipo || !c.spend) continue;
  const T_ = TIPOS[c.tipo];
  if (c.cpr !== null && c.cpr_ant !== null && c.cpr <= c.cpr_ant * 0.95)
    melhorias.push(`• *${c.nome}*: ${T_.custo.toLowerCase()} caiu de ${brl(c.cpr_ant)} para ${brl(c.cpr)} (−${pct((1 - c.cpr / c.cpr_ant) * 100)}%)`);
  if (c.escalada && c.cpr !== null) melhorias.push(`• *${c.nome}*: orçamento aumentado para escalar os resultados`);
  if (c.cpr !== null && T_.meta && c.cpr > T_.meta)
    ajustes.push(`• *${c.nome}*: ${T_.custo.toLowerCase()} em ${brl(c.cpr)}, acima da meta de ${brl(T_.meta)} — vamos testar novos criativos e públicos`);
  else if (c.cpr === null && c.spend >= num(c.tipo === 'visitas' ? cfg.gasto_min_sem_resultado_visita : cfg.gasto_min_sem_resultado_msg))
    ajustes.push(`• *${c.nome}*: investiu ${brl(c.spend)} sem ${T_.rotulo} — vamos revisar a segmentação e os criativos`);
  if (c.freq > num(cfg.frequencia_max)) ajustes.push(`• *${c.nome}*: frequência em ${pct(c.freq)} — vamos renovar os criativos`);
}

// ---------- 8) Saldo da conta (pré-pago: saldo disponível; cartão: valor em uso até a próxima cobrança)
const money = v => { let s = String(v ?? '').replace(/[^\d,.\-]/g, ''); if (!s) return null; const c = s.lastIndexOf(','), p = s.lastIndexOf('.');
  if (c > -1 && p > -1) s = c > p ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, ''); else if (c > -1) s = s.replace(',', '.');
  const n = parseFloat(s); return isNaN(n) ? null : n; };
let saldoTxt = '';
if (conta && conta.id && !conta.error) {
