                       : `pagamento automático no cartão de crédito — ${brl(num(conta.balance) / 100)} em uso até a próxima cobrança`;
  }
}

// ---------- 9) Mensagem
const h = parseInt($now.toFormat('HH'), 10);
const saud = h < 12 ? 'Bom dia' : (h < 18 ? 'Boa tarde' : 'Boa noite');
const primeiroNome = String(cli.cliente).split(/\s+/)[0];
const temVis = T.vis > 0 || ativas.some(c => c.tipo === 'visitas');
