if (melhorias.length) { L.push(''); L.push('✅ *Com base nos parâmetros das campanhas, melhoramos:*'); melhorias.slice(0, 6).forEach(b => L.push(b)); }
L.push(''); L.push('🚧 *Teremos que ajustar essa semana:*');
if (ajustes.length) ajustes.slice(0, 6).forEach(b => L.push(b)); else L.push('• Tudo dentro dos parâmetros — seguimos acompanhando diariamente.');
if (cli.link_relatorio) { L.push(''); L.push('🔗 Segue o link do relatório em tempo real da sua conta, verificada 24h por dia:'); L.push(cli.link_relatorio); }
