L.push(''); L.push('Caso haja alguma dúvida, pode me acionar!'); L.push('Forte abraço! 🚀');
let msg = L.join('\n');
if (msg.length > 6000) msg = msg.slice(0, 5950) + '\n…';

// ---------- 10) Envios
const avisos = [];
if (divergencia) avisos.push(`soma das campanhas (${brl(somaCamp)}) difere do total da conta (${brl(T.spend)})`);
if (!cli.link_relatorio) avisos.push('sem "Link do Relatório" na Planilha Geral');
