const envios = [];
let qtd = 0;
if (divergencia && cfg.bloquear_se_divergente !== false) {
  rec.status = 'NÃO ENVIADO'; rec.obs = avisos.join('; ');
  return saida([{ para: gestor, tipo: 'gestor', texto: `⚠️ *Relatório NÃO enviado — ${cli.cliente}*\n\nA soma do investimento das campanhas (${brl(somaCamp)}) não bate com o total da conta (${brl(T.spend)}) em ${per.rotulo}. Para não haver conflito com o relatório, o envio foi bloqueado.\n\nPrévia:\n\n${msg}`.slice(0, 6500) }], 0);
}
